// Stage 36-A2.1 · code generated by hand
//
// 处理 GET /api/v1/conversations（用户隔离的会话列表）
// 关键契约：
//   - 用户必须登录（middleware 已塞 userID）
//   - 仅返回当前 user_id 的会话（不允许跨用户查询）
//   - 按 updated_at desc 排序（最近活跃在前）
//   - hasMore：取 limit+1 行探测，超 limit 则丢弃末位并标 true
package logic

import (
	"context"
	"errors"

	"emotion-echo-chat-svc/internal/model"
	"emotion-echo-chat-svc/internal/svc"
	"emotion-echo-chat-svc/internal/types"
	sharedmw "github.com/emotion-echo/shared/pkg/middleware"
)

// ListConversationsLogic 处理 GET /api/v1/conversations
type ListConversationsLogic struct {
	ctx    context.Context
	svcCtx *svc.ServiceContext
}

func NewListConversationsLogic(ctx context.Context, svcCtx *svc.ServiceContext) *ListConversationsLogic {
	return &ListConversationsLogic{

		ctx:    ctx,
		svcCtx: svcCtx,
	}
}

// ListConversations 列出当前用户的会话，按 updated_at desc
func (l *ListConversationsLogic) ListConversations(req *types.ListConversationsReq) (resp *types.ListConversationsResp, err error) {
	uid, ok := l.ctx.Value(sharedmw.CtxUserIDKey{}).(int64)
	if !ok || uid <= 0 {
		return nil, errors.New("unauthorized: missing user id")
	}

	limit := req.Limit
	if limit <= 0 {
		limit = 20
	}
	offset := req.Offset
	if offset < 0 {
		offset = 0
	}

	// CL-05 Phase 5：三条路径 ——
	//   ① 带游标             ⇒ keyset 分页（主路径）
	//   ② 无游标且 offset==0 ⇒ keyset **首页**（与 ① 共用实现 ⇒ NextCursor 一定给得出）
	//   ③ 无游标且 offset>0  ⇒ 既有 offset 分页（向后兼容旧客户端）
	cursorAt, cursorID, err := decodeConversationCursor(req.Cursor)
	if err != nil {
		return nil, err
	}

	var convs []model.Conversation
	var hasMore bool
	if req.Cursor == "" && offset > 0 {
		convs, err = l.svcCtx.ConversationRepo.ListConversations(l.ctx, uid, limit+1, offset)
		if err != nil {
			return nil, err
		}
		hasMore = len(convs) > limit
		if hasMore {
			convs = convs[:limit]
		}
	} else {
		convs, hasMore, err = l.svcCtx.ConversationRepo.ListConversationsPage(l.ctx, uid, limit, cursorAt, cursorID)
		if err != nil {
			return nil, err
		}
	}

	out := &types.ListConversationsResp{
		List:    make([]types.ConversationView, 0, len(convs)),
		HasMore: hasMore,
	}
	for _, c := range convs {
		out.List = append(out.List, types.ConversationView{
			Id:        c.ID,
			UserId:    c.UserID,
			Title:     c.Title,
			MsgCount:  c.MessageCount,
			Status:    int(c.Status),
			IsPinned:  c.Pinned,
			CreatedAt: c.CreatedAt.UnixMilli(),
			UpdatedAt: c.UpdatedAt.UnixMilli(),
			// CL-06：本会话当前角色。**投影点必须显式赋值** —— 漏了就会出现
			// "库里写对、接口恒回 0"（CL-06 Phase 8 经网关实测抓到过，见
			// listconversationslogic_agent_test.go 的回归钉）
			AgentId: derefAgentID(c.AgentID),
		})
	}
	// 下一页游标 = 本页**最后一条**的复合键（序为 updated_at DESC ⇒ 末行即本页最旧）。
	// 没有更多时留空 —— 前端一眼判定"到底了"，不必再靠 hasMore 推断。
	if hasMore && len(convs) > 0 {
		last := convs[len(convs)-1]
		out.NextCursor = encodeConversationCursor(last.UpdatedAt, last.ID)
	}
	return out, nil
}
